// The feature flags that gate a cloud vault function (§2.6.6, Config Profile `features`). Names and
// defaults come from the schema (`@clarae/api-client/features`, generated by `task gen`), the same
// as the Go core's: a flag missing from the effective configuration takes the schema's default.
import { useQuery } from '@tanstack/react-query';
import { featureEnabled, type Feature } from '@clarae/api-client/features';
import { cloudKeys } from './CloudVaultsTable';
import type { CloudPort } from './port';

/** Flags read by the components of this package and by their hosts. */
export type CloudFeature = typeof Feature.Sharing | typeof Feature.WebWorkbench;

/** Whether a flag is on: its value when the configuration sets it, the schema's default otherwise. */
export function featureOn(
  features: Record<string, boolean> | undefined,
  name: CloudFeature,
): boolean {
  return featureEnabled(features, name);
}

/** The `features` object of an effective configuration, keeping only the boolean values. */
export function featuresOf(config: Record<string, unknown> | undefined): Record<string, boolean> {
  const raw = config?.['features'];
  const out: Record<string, boolean> = {};
  if (raw && typeof raw === 'object')
    for (const [k, v] of Object.entries(raw as Record<string, unknown>))
      if (typeof v === 'boolean') out[k] = v;
  return out;
}

/**
 * A flag of the effective configuration, through the port: `on` is the product default while the
 * configuration loads or when it cannot be read (the server enforces what it must); `ready` tells
 * whether the configuration has answered, so a component can wait before fetching what it gates.
 */
export function useFeatureFlag(
  port: CloudPort,
  name: CloudFeature,
): { on: boolean; ready: boolean } {
  const q = useQuery({
    queryKey: cloudKeys.features(port),
    queryFn: () => port.getFeatures(),
    staleTime: 60_000,
    // A configuration that could not be read is not asked again by every component that mounts:
    // a refetch puts the query back to `pending`, the components that wait for `ready` unmount
    // their children, which mount again when it fails, and so on (the flag is the default meanwhile).
    retryOnMount: false,
  });
  return { on: featureOn(q.data, name), ready: !q.isPending };
}

/** Whether a flag is on (see useFeatureFlag). */
export function useFeature(port: CloudPort, name: CloudFeature): boolean {
  return useFeatureFlag(port, name).on;
}
